public class Main{static long xsNext(long x){x^=x<<13;x^=x>>>7;x^=x<<17;return x;}public static void main(String[]a){int w=256; byte[] A=new byte[w*w],B=new byte[w*w]; long r=12345; for(int i=0;i<w*w;i++){r=xsNext(r); A[i]=(byte)Long.remainderUnsigned(r,256);} for(int p=0;p<8;p++){blur(A,B,w); blur(B,A,w);} long t=0; for(byte v:A) t+=v&0xFF; System.out.println(w); System.out.println(t);} static void blur(byte[]s,byte[]d,int w){for(int y=1;y<w-1;y++)for(int x=1;x<w-1;x++){int i=y*w+x; int sm=(s[i-w-1]&0xFF)+(s[i-w]&0xFF)*2+(s[i-w+1]&0xFF)+(s[i-1]&0xFF)*2+(s[i]&0xFF)*4+(s[i+1]&0xFF)*2+(s[i+w-1]&0xFF)+(s[i+w]&0xFF)*2+(s[i+w+1]&0xFF); d[i]=(byte)(sm>>4);}}}